        fl_value fl_t720 = fl_nothing();
        FL_TRY(fl_field_get(ctx, chtenie, "значение", &fl_t720, error));
        fl_value fl_t721 = fl_nothing();
        FL_TRY(kompilyator_flang_token_literala(ctx, fl_t720, nomer, mesto, &fl_t721, error));
