/* Тело «Снять окончание»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_snyat_okonchanie_body(fl_ctx *ctx, fl_value nizhnee, fl_value okonchaniya, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Снять окончание", error));
    if (fl_chain_empty(okonchaniya)) {
      *result = nizhnee;
      return FL_OK;
    } else if (fl_chain_cons(okonchaniya)) {
      const fl_value okonchanie = fl_chain_head(okonchaniya); /* голова «окончание» */
      const fl_value prochie = fl_chain_tail(okonchaniya); /* хвост «прочие» */
      fl_value fl_t1393 = fl_nothing(); /* «длина» */
      FL_TRY(fl_b_dlina(ctx, nizhnee, &fl_t1393, error));
      fl_value fl_t1394 = fl_nothing(); /* «длина» */
      FL_TRY(fl_b_dlina(ctx, okonchanie, &fl_t1394, error));
      fl_value fl_t1395 = fl_nothing();
      FL_TRY(fl_sub(ctx, fl_t1393, fl_t1394, &fl_t1395, error));
      const fl_value ostatok = fl_t1395; /* пусть «остаток» */
      fl_value fl_t1396 = fl_nothing();
      FL_TRY(kompilyator_flang_konchaetsya_na(ctx, nizhnee, okonchanie, &fl_t1396, error));
      bool fl_t1397 = false;
      FL_TRY(fl_cond(ctx, fl_t1396, &fl_t1397, error));
      fl_value fl_t1398 = fl_nothing();
      if (fl_t1397) {
        fl_value fl_t1399 = fl_nothing();
        FL_TRY(kompilyator_flang_naimenshaya_osnova(ctx, &fl_t1399, error));
        fl_value fl_t1400 = fl_nothing();
        FL_TRY(fl_gte(ctx, ostatok, fl_t1399, &fl_t1400, error));
        fl_t1398 = fl_t1400;
      } else {
        fl_t1398 = fl_flag(false);
      }
      bool fl_t1401 = false;
      FL_TRY(fl_cond(ctx, fl_t1398, &fl_t1401, error));
      if (fl_t1401) {
        fl_value fl_t1402 = fl_nothing(); /* «подстрока» */
        FL_TRY(fl_b_podstroka(ctx, nizhnee, fl_number(1.0), ostatok, &fl_t1402, error));
        *result = fl_t1402;
        return FL_OK;
      } else {
        const fl_value fl_t1403 = nizhnee;
        nizhnee = fl_t1403;
        okonchaniya = prochie;
        continue;
      }
    } else {
      return fl_match_fail(ctx, okonchaniya, error);
    }
  }
}

/*
 * Функция flang «Снять окончание».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param nizhnee — «нижнее»: строка
 * @param okonchaniya — «окончания»: список: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_snyat_okonchanie(fl_ctx *ctx, fl_value nizhnee, fl_value okonchaniya, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Снять окончание", error));
  {
    const fl_status status = kompilyator_flang_snyat_okonchanie_body(ctx, nizhnee, okonchaniya, result, error);
    fl_leave(ctx);
    return status;
  }
}

